import 'package:flutter/material.dart';
import 'package:video_player/video_player.dart';
import '../../../services/tv/auren_tv_service.dart';
class AurenTvScreen extends StatefulWidget { const AurenTvScreen({super.key}); @override State<AurenTvScreen> createState()=>_State(); }
class _State extends State<AurenTvScreen>{ String country='',category='',query=''; bool lowData=false,onlyFavorites=false; Set<String> favorites={}; VideoPlayerController? player;
 @override void initState(){super.initState();AurenTvService.instance.favorites().then((v){if(mounted)setState(()=>favorites=v);});}\n @override void dispose(){player?.dispose();super.dispose();}\n Future<void> toggleFavorite(AurenTvChannel c) async {final v=!favorites.contains(c.id);await AurenTvService.instance.setFavorite(c.id,v);if(mounted)setState(()=>v?favorites.add(c.id):favorites.remove(c.id));}
 Future<void> play(AurenTvChannel c) async {await player?.dispose(); final p=VideoPlayerController.networkUrl(Uri.parse(c.url)); setState(()=>player=p); try{await p.initialize();if(!lowData)await p.play();if(mounted)setState((){});}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تعذر تشغيل القناة؛ قد تكون غير متاحة أو محجوبة جغرافياً.')));}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('AUREN TV • World')),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:TextField(decoration:const InputDecoration(labelText:'Country / البلد'),onChanged:(v)=>country=v)),const SizedBox(width:8),Expanded(child:TextField(decoration:const InputDecoration(labelText:'Category / الفئة'),onChanged:(v)=>category=v)),IconButton(onPressed:()=>setState((){}),icon:const Icon(Icons.search))])),Padding(padding:const EdgeInsets.symmetric(horizontal:12),child:Wrap(spacing:8,children:[for(final x in ['Africa','Asia','Europe','Americas','Oceania'])ChoiceChip(label:Text(x),selected:category==x,onSelected:(_)=>setState(()=>category=category==x?'':x)),FilterChip(label:const Text('المفضلة'),selected:onlyFavorites,onSelected:(v)=>setState(()=>onlyFavorites=v)),FilterChip(label:const Text('Low Data'),selected:lowData,onSelected:(v)=>setState(()=>lowData=v))])),if(lowData)const Text('توفير البيانات: التشغيل يدوي ولا يبدأ تلقائياً.'),if(player?.value.isInitialized==true)AspectRatio(aspectRatio:player!.value.aspectRatio,child:VideoPlayer(player!)),Expanded(child:FutureBuilder<List<AurenTvChannel>>(future:AurenTvService.instance.load(country:country,category:category),builder:(context,s){if(s.hasError)return Center(child:Text('تعذر تحميل القنوات: '+s.error.toString()));if(!s.hasData)return const Center(child:CircularProgressIndicator());final xs=s.data!.where((c)=>(query.isEmpty||('${c.name} ${c.country} ${c.language} ${c.category}').toLowerCase().contains(query.toLowerCase()))&&(!onlyFavorites||favorites.contains(c.id))).toList();return ListView.separated(padding:const EdgeInsets.all(12),itemCount:xs.length,separatorBuilder:(_,__)=>const SizedBox(height:6),itemBuilder:(_,i){final c=xs[i];return Card(child:ListTile(leading:c.logo.isEmpty?const CircleAvatar(child:Icon(Icons.tv)):CircleAvatar(backgroundImage:NetworkImage(c.logo)),title:Text(c.name),subtitle:Text(c.country+' • '+c.language+' • '+c.category),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>toggleFavorite(c),icon:Icon(favorites.contains(c.id)?Icons.star:Icons.star_border)),const Icon(Icons.play_circle_fill)]),onTap:()=>play(c)));});}))]));
}